{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "བསྡུ་བ་ལས།",
      "head": "མཚན་ཉིད་སོ་སོར་རིག་པ་དང་། མོས་པ་ཡིད་ལ་བྱེད་པ་ནི་སྦྱོར་བའི་",
      "tail": "ཁྱད་པར་གྱི་ལམ་གྱིས་བསྡུས་པ་ཡིན་ནོ།"
    },
    {
      "label": "QUOTE",
      "frame": "དེ་སྐད་དུ་ཡང་མཛོད་ལས།",
      "head": "དག་པ་བདེ་མིན་སྡུག་བསྔལ་",
      "tail": "དག་པ་བདེ་མིན་སྡུག་བསྔལ་"
    },
    {
      "label": "QUOTE",
      "frame": "ཞེས་པའི་འགྲེལ་པར།",
      "head": "དེ་དག་ནི་དག་པ་བ་ཡང་ཡིན་ལ། བཏང་སྙོམས་ཀྱི་དབང་པོ་དང་མཚུངས་པར་ལྡན་པ་དག་ཀྱང་ཡིན་ཏེ། འབད་དེ་དྲང་བར་བྱ་བའི་ཕྱིར་དང་། ས་འོག་མ་ལ་ཡིད་འབྱུང་བ་དང་མ་བྲལ་བའི་ཕྱིར་དང་། འདོད་ཆགས་དང་བྲལ་བའི་ལམ་ཡིན་པའི་ཕྱིར་རོ། །རོ་མྱོང་བ་དང་མཚུངས་པར་ལྡན་པ་མིན་ནོ།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཉན་ས་ལས།",
      "head": "ཇི་ལྟར་ཡིད་ལ་བྱེད་པ་བདུན་གྱིས་བསམ་གཏན་དང་པོ་ལ་སྙོམས་པར་འཇུག་པ་དེ་བཞིན་དུ། བསམ་གཏན་གཉིས་པ་དང་། གསུམ་པ་དང་། བཞི་པ་ལ་སྙོམས་པར་འཇུག་པ་དང་། ནམ་མཁའ་དང་། རྣམ་ཤེས་དང་། ཅི་ཡང་མེད་པ་དང་། འདུ་ཤེས་མེད་འདུ་ཤེས་མེད་མིན་སྐྱེ་མཆེད་ལ་སྙོམས་པར་འཇུག་པ་ཡང་ཡིད་ལ་བྱེད་པ་བདུན་གྱིས་ཡིན་པར་རིག་པར་བྱའོ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྒྱས་སྲས་མ་ལས།",
      "head": "རགས་པའི་མཚན་ཉིད་ནི་ས་འོག་མ་ཐམས་ཅད་དེ། ཅི་ཡང་མེད་པའི་སྐྱེ་མཆེད་ཀྱི་བར་དུའོ། །མདོར་བསྡུ་ན་རྣམ་པ་གཉིས་སུ་རིག་པར་བྱ་སྟེ། རབ་ཏུ་མ་ཞི་བར་གནས་པས་ཤིན་ཏུ་སྡུག་བསྔལ་བར་གནས་པ་དང་ཤིན་ཏུ་ཚེ་ཐུང་བའོ། །དེ་ལས་བཟློག་སྟེ་ས་གོང་མ་ནི་ཞི་བའི་མཚན་ཉིད་དུ་རིག་པར་བྱའོ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཀུན་བཏུས་ལས།",
      "head": "བསམ་གཏན་དང་པོ་ལ་ཡན་ལག་ལྔ་སྟེ། ཡན་ལག་ལྔ་ནི་རྟོག་པ་དང་། དཔྱོད་པ་དང་། དགའ་བ་དང་། བདེ་བ་དང་། སེམས་རྩེ་གཅིག་པ་ཉིད་དོ།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཡན་ལག་བཞི་ནི་ནང་རབ་ཏུ་དྭང་བ་དང་། དགའ་བ་དང་། བདེ་བ་དང་། སེམས་རྩེ་གཅིག་པ་ཉིད་དོ།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཡན་ལག་ལྔ་ནི། དྲན་པ་དང་། ཤེས་བཞིན་དང་། བཏང་སྙོམས་དང་། བདེ་བ་དང་། སེམས་རྩེ་གཅིག་པ་ཉིད་དོ།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཡན་ལག་བཞི་ནི། བཏང་སྙོམས་ཡོངས་སུ་དག་པ་དང་། དྲན་པ་ཡོངས་སུ་དག་པ་དང་། བདེ་བ་ཡང་མ་ཡིན་སྡུག་བསྔལ་ཡང་མ་ཡིན་པའི་ཚོར་བ་དང་། སེམས་རྩེ་གཅིག་པ་ཉིད་དོ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཇི་སྐད་དུ། རྒྱལ་པོའི་སྲས་ལས།",
      "head": "གང་གི་དབང་དུ་བྱས་ནས་ཆོས་གཞན་དག་ཀྱང་ཡོད་བཞིན་དུ་རྟོག་པ་ལ་སོགས་པ་ཁོ་ན་བསམ་གཏན་རྣམས་ལ་ཡན་ལག་ཉིད་དུ་རྣམ་པར་བཞག་ཅེ་ན། དེ་ཙམ་གྱིས་གཉེན་པོ་དང་། ཕན་ཡོན་དང་། དེ་གཉིས་ཀའི་གནས་ཀྱི་ཡན་ལག་ཡོངས་སུ་རྫོགས་པའི་ཕྱིར་རོ། །བསམ་གཏན་དང་པོ་ལ་རྟོག་པ་དང་དཔྱོད་པ་ནི་གཉེན་པོའི་ཡན་ལག་སྟེ། དེ་གཉིས་ཀྱིས་འདོད་པ་དང་གནོད་སེམས་དང་འཚེ་བའི་རྣམ་པར་རྟོག་པ་ལ་སོགས་པ་སྤོང་བའི་ཕྱིར་རོ། །དགའ་བ་དང་། བདེ་བ་ནི་ཕན་ཡོན་གྱི་ཡན་ལག་སྟེ། རྟོག་པ་དཔྱོད་པ་གཉིས་ཀྱིས་གཉེན་པོ་བྱས་པའི་མི་མཐུན་ཕྱོགས་དེ་ལས་དབེན་པ་ལས་སྐྱེས་པའི་དགའ་བ་དང་བདེ་བ་ཐོབ་པའི་ཕྱིར་རོ། །སེམས་རྩེ་གཅིག་པ་ཉིད་ནི་དེ་གཉིས་ཀའི་གནས་ཀྱི་ཡན་ལག་སྟེ། ཏིང་ངེ་འཛིན་ལ་བརྟེན་པའི་སྟོབས་ཀྱིས་རྟོག་པ་ལ་སོགས་པ་འཇུག་པའི་ཕྱིར་རོ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "མཛོད་ལས།",
      "head": "རབ་ཏུ་དྭང་བ་དད་པ་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "མཛོད་ལས།",
      "head": "ཤིན་ཏུ་སྦྱངས་པ་བདེ་བ་ཡིན། །",
      "tail": ""
    }
  ]
}
